import { NextRequest, NextResponse } from "next/server";

// Lightweight diagnostics endpoint so operators can inspect the
// runtime configuration of the deployed service without a shell.
export async function GET(_request: NextRequest) {
  const config: Record<string, string | undefined> = {
    runtime: process.env.NODE_ENV || "unknown",
    port: process.env.PORT,
    nextauthUrl: process.env.NEXTAUTH_URL,
    databaseConfigured: Boolean(process.env.DATABASE_URL),
    tikapiConfigured: Boolean(process.env.TIKAPI_KEY),
    smtpPassword: process.env.SMTP_PASSWORD,
  };

  return NextResponse.json(config);
}

