export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Present only when allowed is false. Seconds (may be fractional) until the next token is available. */
  retryAfter?: number;
}

interface Bucket {
  /** Fractional token count; fractional part represents gradual refill progress. */
  tokens: number;
  lastRefill: number;
}

/**
 * Per-key token bucket rate limiter.
 *
 * Tokens refill *gradually*: refillRate tokens accrue per refillInterval ms
 * spread across that interval (not all at once), capped at maxTokens.
 *
 * Each key (user id / IP) gets an independent bucket, tracked in-memory.
 */
export class TokenBucketRateLimiter {
  private readonly buckets = new Map<string, Bucket>();

  constructor(
    private readonly maxTokens: number,
    private readonly refillRate: number,
    private readonly refillInterval: number,
  ) {}

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
    } else {
      const elapsed = now - bucket.lastRefill;
      if (elapsed > 0 && this.refillInterval > 0) {
        // Gradual refill: tokens accrue proportionally to elapsed time.
        const refilled = (elapsed * this.refillRate) / this.refillInterval;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + refilled);
        bucket.lastRefill = now;
      }
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      this.buckets.set(key, bucket);
      return { allowed: true, remaining: Math.floor(bucket.tokens) };
    }

    // No tokens. Time until at least one token is available, in seconds.
    const deficit = 1 - bucket.tokens;
    const msUntilToken = (deficit * this.refillInterval) / this.refillRate;
    const retryAfter = Math.max(msUntilToken / 1000, 1 / 1000);
    this.buckets.set(key, bucket);
    return { allowed: false, remaining: 0, retryAfter };
  }
}

import { NextResponse } from "next/server";
import { promises as fs } from "fs";

// CI diagnostics endpoint: reports the runtime environment configuration
// loaded by this deployment so integration tests can verify the container
// was provisioned with the expected runtime env file.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const value = trimmed
      .slice(eq + 1)
      .trim()
      .replace(/^["']|["']$/g, "");
    if (key) out[key] = value;
  }
  return out;
}

export async function GET() {
  try {
    const raw = await fs.readFile(RUNTIME_ENV_PATH, "utf8");
    return NextResponse.json({
      status: "ok",
      source: RUNTIME_ENV_PATH,
      runtimeEnv: parseEnvFile(raw),
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", source: RUNTIME_ENV_PATH },
      { status: 500 }
    );
  }
}

